INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(44011, 'Leviticus 16:31', 'Leviticus', 16, 31, 'دا به د سبت په شان د ارام کولو سپېڅلې ورځ وي، په دې ورځ باید تاسو روژه ونیسئ. په دغو مقرراتو باندې دې د تل دپاره عمل وشي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus16_verse_31.mp3', '', 1761754199, 1761754199),
(44012, 'Leviticus 16:32', 'Leviticus', 16, 32, 'هغه کاهن چې مسح شوی وي او د خپل پلار په ځای د لوی کاهن په توګه وقف شوی وي، هغه دې کفاره ادا کړي. هغه دې د کتان سپېڅلي کالي واغوندي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus16_verse_32.mp3', '', 1761754199, 1761754199),
(44013, 'Leviticus 16:33', 'Leviticus', 16, 33, 'او دا مراسم دې سرته ورسوي د دې په خاطر چې ډېر سپېڅلی ځای، د سپېڅلې خېمې پاتې برخې او د قربانۍ ځای پاک کړي او د کاهنانو او ټول قوم دپاره کفاره ادا کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus16_verse_33.mp3', '', 1761754199, 1761754199),
(44014, 'Leviticus 16:34', 'Leviticus', 16, 34, 'د اسراییلیانو د ټولو ګناهونو دپاره دې په کال کې یوځل کفاره ادا شي. په دې مقرراتو باندې دې د تل دپاره عمل وشي.» نو څنګه چې څښتن موسی ته امر کړی ؤ، هماغسې وشول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus16_verse_34.mp3', '', 1761754199, 1761754199),
(44015, 'Numbers 22:1', 'Numbers', 22, 1, 'اسراییلیان د هغه ځای څخه روان شول او د موآب په ډاګونو کې د اردن د سیند ختیځ خواته اریحا ته مخامخ یې خېمې ودرولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_1.mp3', '', 1761754199, 1761754199),
(44016, 'Numbers 22:6', 'Numbers', 22, 6, 'هغوی ډېر قوي دي او مونږ ورته ماتې نه شو ورکولای، نو ایا ته به راشې او زما دپاره به په هغوی باندې لعنت ووایې؟ کېدای شي بیا مونږ وکولای شو چې هغوی ته ماتې ورکړو او د دې خاورې څخه یې وشړو. زه پوهېږم چې هرچا ته چې ته برکت ورکړې هغه به برکت ومومي، خو په هرچا باندې چې لعنت ووایې په هغه باندې به لعنت راشي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_6.mp3', '', 1761754199, 1761754199),
(44017, 'Numbers 22:7', 'Numbers', 22, 7, 'د موآب او د مدیان مشران لاړل او پیسې یې د ځان سره واخیستلې چې بلعام ته یې د فال دپاره ورکړي. کله چې هغوی د هغه کور ته ورسېدل، د بالاق پیغام یې ورکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_7.mp3', '', 1761754199, 1761754199),
(44018, 'Numbers 22:8', 'Numbers', 22, 8, 'بلعام په ځواب کې وویل: «شپه دلته تېره کړئ او سبا به بېرته تاسو ته د څښتن هغه ځواب راوړم چې ماته یې راکوي.» نو مشران د هغه په کور کې پاتې شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_8.mp3', '', 1761754199, 1761754199),
(44019, 'Numbers 22:9', 'Numbers', 22, 9, 'په هماغه شپه خدای بلعام ته ورغی او پوښتنه یې ترې وکړه: «ستا په کور کې دا خلک څوک دي؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_9.mp3', '', 1761754199, 1761754199),
(44020, 'Numbers 22:10', 'Numbers', 22, 10, 'بلعام په ځواب کې وویل: «دا د موآب د پاچا بالاق استازي دي. هغه دوی رالېږلي دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_10.mp3', '', 1761754199, 1761754199),
(44021, 'Numbers 22:11', 'Numbers', 22, 11, 'چې ما د دې دپاره د ځان سره موآب ته بوځي چې په هغو خلکو باندې لعنت ووایم چې د مصر څخه هلته راغلي دي. هغوی په ټول وطن کې خپاره شوي دي او دی غواړي چې ویې شړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_11.mp3', '', 1761754199, 1761754199),
(44022, 'Numbers 22:12', 'Numbers', 22, 12, 'خو خدای په ځواب کې وویل: «د بالاق د استازو سره مه ځه. ما هغو خلکو ته چې د مصر څخه راغلي دي برکت ورکړی دی، نو په هغوی باندې لعنت مه وایه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_12.mp3', '', 1761754199, 1761754199),
(44023, 'Numbers 22:13', 'Numbers', 22, 13, 'سهار بلعام د بالاق استازو ته وویل: «بېرته خپل وطن ته لاړ شئ. څښتن ماته اجازه نه راکوي چې ستاسو سره لاړ شم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_13.mp3', '', 1761754199, 1761754199),
(44024, 'Numbers 22:14', 'Numbers', 22, 14, 'نو هغوی لاړل او بالاق ته یې وویل چې بلعام د راتګ څخه انکار وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_14.mp3', '', 1761754199, 1761754199),
(44025, 'Numbers 22:15', 'Numbers', 22, 15, 'بیا بالاق زیات شمېر مشران ورولېږل چې د لومړنۍ ډلې څخه ډېر مهم خلک په کې وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_15.mp3', '', 1761754199, 1761754199),
(44026, 'Numbers 22:16', 'Numbers', 22, 16, 'هغوی بلعام ته ورغلل او ورته ویې ویل چې بالاق وایي: «بلعامه، ته باید خامخا راشې!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_16.mp3', '', 1761754199, 1761754199),
(44027, 'Numbers 22:17', 'Numbers', 22, 17, 'زه به ډېرې پیسې درکړم او هرڅه چې ته غواړې هغه به وکړم. راشه او زما دپاره په دغو خلکو باندې لعنت ووایه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_17.mp3', '', 1761754199, 1761754199),
(44028, 'Numbers 22:18', 'Numbers', 22, 18, 'خو بلعام په ځواب کې وویل: «حتی که چېرې بالاق ماته خپله ماڼۍ هم راکړي چې د سرو زرو او سپینو زرو څخه ډکه وي، حتی زه به په یوې ډېرې کوچنۍ موضوع هم د خپل څښتن خدای د حکم څخه سرغړونه ونه کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_18.mp3', '', 1761754199, 1761754199),
(44029, 'Numbers 22:19', 'Numbers', 22, 19, 'تاسو کولای شئ چې دلته شپه تېره کړئ لکه څنګه چې هغو نورو تېره کړه. زه به دا معلومه کړم چې څښتن په دې هکله ماته نور څه وایي یا نه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_19.mp3', '', 1761754199, 1761754199),
(44030, 'Numbers 22:20', 'Numbers', 22, 20, 'په هغه شپه خدای بلعام ته وویل: «که چېرې هغه کسان تاته راغلل او درڅخه یې وغوښتل چې ورسره لاړ شې، نو ځان تیار کړه او ورسره لاړ شه، خو یوازې هغه کار به کوې چې زه یې درته وایم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_20.mp3', '', 1761754199, 1761754199),
(44031, 'Numbers 22:21', 'Numbers', 22, 21, 'نو بلعام سهار راپاڅېده او په خپله خره باندې یې کته واچوله او د موآبیانو د مشرانو سره لاړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_21.mp3', '', 1761754199, 1761754199),
(44032, 'Numbers 22:22', 'Numbers', 22, 22, 'خدای د بلعام په تللو په قهر شو. بلعام په خپلې خرې باندې سپور ؤ او خپل دوه نوکران یې ورسره وو. د څښتن فرښته په لاره کې ودرېدله چې مخه یې ونیسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_22.mp3', '', 1761754199, 1761754199),
(44033, 'Numbers 22:23', 'Numbers', 22, 23, 'کله چې د بلعام خرې د څښتن فرښته ولیدله چې په لاره کې ولاړه ده او توره یې په لاس کې ده، نو لاره یې پرېښودله او په پټي کې روانه شوه. بلعام خره ووهله چې بېرته یې لارې ته راولي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_23.mp3', '', 1761754199, 1761754199),
(44034, 'Numbers 22:24', 'Numbers', 22, 24, 'بیا فرښته د انګورو د دوو باغونو په منځ کې په یوه تنګه لاره کې چې دواړو خواو ته یې دېوال ؤ، ودرېدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_24.mp3', '', 1761754199, 1761754199),
(44035, 'Numbers 22:25', 'Numbers', 22, 25, 'کله چې خرې فرښته ولیدله، هغه دېوال ته دومره نژدې روانه شوه چې د بلعام پښه په دېوال باندې وسولېدله. بلعام بیا خره ووهله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_25.mp3', '', 1761754199, 1761754199),
(44036, 'Numbers 22:26', 'Numbers', 22, 26, 'فرښته یوځل بیا مخکې لاړه او په یو داسې تنګ ځای کې ودرېدله چې د خرې دپاره بیخي ځای نه ؤ چې ښي یا چپ خواته وګرځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_26.mp3', '', 1761754199, 1761754199),
(44037, 'Numbers 22:27', 'Numbers', 22, 27, 'په دې وخت کې چې کله خرې فرښته ولیدله، نو هغه پرېوتله. بلعام په قهر شو او په خپله امسا باندې یې د خرې په وهلو پیل وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_27.mp3', '', 1761754199, 1761754199),
(44038, 'Numbers 22:28', 'Numbers', 22, 28, 'بیا څښتن خرې ته دا توان ورکړ چې خبرې وکړي او خرې بلعام ته وویل: «ما ستا سره څه کړي دي چې درې ځلې دې ووهلم؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_28.mp3', '', 1761754199, 1761754199),
(44039, 'Numbers 22:29', 'Numbers', 22, 29, 'بلعام په ځواب کې وویل: «تا راڅخه کم عقل جوړ کړ! که چېرې توره راسره وای، نو ته به مې همدلته وژلې وای!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_29.mp3', '', 1761754199, 1761754199),
(44040, 'Numbers 22:30', 'Numbers', 22, 30, 'خرې په ځواب کې وویل: «زه هماغه خره نه یم چې ټول عمر راباندې سپور شوی یې؟ ایا مخکې مې کله درسره داسې کار کړی ؤ؟» بلعام په ځواب کې وویل: «نه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_30.mp3', '', 1761754199, 1761754199),
(44041, 'Numbers 22:31', 'Numbers', 22, 31, 'بیا څښتن د بلعام سترګې پرانیستلې او هغه فرښته یې ولیدله چې د تورې سره په لاره کې ولاړه وه. بلعام خپل ځان پړمخې په ځمکه باندې وغورځاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_31.mp3', '', 1761754199, 1761754199),
(44042, 'Numbers 22:32', 'Numbers', 22, 32, 'فرښتې وویل: «ولې دې خپله خره درې ځلې ووهله؟ دا زه وم چې ستا لاره مې بنده کړې وه، ځکه چې ته باید موآب ته لاړ نه شې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_32.mp3', '', 1761754199, 1761754199),
(44043, 'Numbers 22:33', 'Numbers', 22, 33, 'که چېرې ستا خرې زه درې ځلې لیدلې نه وای او ودرېدلې نه وای، ما به ته وژلی وای او خره به مې ژوندۍ پریښې وای.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_33.mp3', '', 1761754199, 1761754199),
(44044, 'Numbers 22:34', 'Numbers', 22, 34, 'بلعام په ځواب کې وویل: «ما ګناه وکړه. زه نه پوهېدم چې ته په لاره کې ولاړه وې چې زما مخه ونیسې. که چېرې ته فکر کوې چې دا بده ده چې زه لاړ شم، نو زه به کور ته ستون شم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_34.mp3', '', 1761754199, 1761754199),
(44045, 'Numbers 22:35', 'Numbers', 22, 35, 'خو فرښتې وویل: «د دې خلکو سره لاړ شه، خو یوازې هغه څه به وایې چې زه یې درته وایم.» نو بلعام د هغو مشرانو سره روان شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_35.mp3', '', 1761754199, 1761754199),
(44046, 'Numbers 22:36', 'Numbers', 22, 36, 'کله چې بالاق واورېدل چې بلعام راروان دی، هغه لاړ چې په عار کې یعنې هغه ښار کې چې د ارنون په سیند باندې د موآب د سرحد سره پروت دی د هغه سره ملاقات وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_36.mp3', '', 1761754199, 1761754199),
(44047, 'Numbers 22:37', 'Numbers', 22, 37, 'بالاق بلعام ته وویل: «کله چې اول ځل ما راوغوښتلې ولې رانغلې؟ ایا تا دا فکر کاوه چې ما نه شو کولای چې پوره انعام درکړم؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_37.mp3', '', 1761754199, 1761754199),
(44048, 'Numbers 22:38', 'Numbers', 22, 38, 'بلعام په ځواب کې وویل: «زه اوس تاته راغلی یم، خو زه څه قدرت لرم؟ زه اوس یوازې هغه څه ویلی شم چې خدای یې راته ووایي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_38.mp3', '', 1761754199, 1761754199),
(44049, 'Numbers 22:39', 'Numbers', 22, 39, 'نو بلعام د بالاق سره د حصوت ښار ته لاړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_39.mp3', '', 1761754199, 1761754199),
(44050, 'Numbers 22:40', 'Numbers', 22, 40, 'بالاق هلته غویان او پسونه قرباني کړل او لږه غوښه یې بلعام او هغو مشرانو ته چې د هغه سره وو، ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_40.mp3', '', 1761754199, 1761754199),
(44051, 'Numbers 22:41', 'Numbers', 22, 41, 'بالاق سهار بلعام د بموت بعل ښار ته پورته بوته. د هغه ځای څخه بلعام ځینې اسراییلیان لیدلی شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers22_verse_41.mp3', '', 1761754199, 1761754199),
(44052, 'Numbers 15:1', 'Numbers', 15, 1, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers15_verse_1.mp3', '', 1761754199, 1761754199),
(44053, 'Numbers 15:2', 'Numbers', 15, 2, '«د اسراییلو قوم ته دا مقررات ورکړه چې هغوی یې په هغې خاوره کې چې زه یې ورته ورکوم مراعت کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers15_verse_2.mp3', '', 1761754199, 1761754199),
(44054, 'Numbers 15:3', 'Numbers', 15, 3, 'تاسو کولای شئ چې د رمې یا پادې څخه یو حیوان د سوځېدونکې نذرانې یا د نذر د قربانۍ یا د خپلې خوښې نذرانې یا ستاسو د مذهبي اخترونو د نذرانو په توګه څښتن ته وړاندې کړئ. د دغو نذرانو بوی په څښتن باندې ښه لګیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers15_verse_3.mp3', '', 1761754199, 1761754199),
(44055, 'Numbers 15:6', 'Numbers', 15, 6, 'کله چې یو پسه وړاندې کیږي، دوه کیلو ګرامه داسې اوړه چې یونیم لیتر د زیتونو تېل ورسره ګډ وي د غلې دانې د نذرانې په توګه دې وړاندې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers15_verse_6.mp3', '', 1761754199, 1761754199),
(44056, 'Numbers 15:7', 'Numbers', 15, 7, 'یونیم لیتر شراب دې هم د څښلو د نذرانې په توګه ورسره وي. د دغو قربانیو بوی په څښتن باندې ښه لګیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers15_verse_7.mp3', '', 1761754199, 1761754199),
(44057, 'Numbers 15:8', 'Numbers', 15, 8, 'کله چې یو غویی څښتن ته د سوځېدونکې نذرانې یا د نذر د قربانۍ یا د سلامتۍ د نذرانې په توګه وړاندې کیږي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers15_verse_8.mp3', '', 1761754199, 1761754199),
(44058, 'Numbers 15:9', 'Numbers', 15, 9, 'د غلې دانې نذرانه دې د درې کیلو ګرامو داسې اوړو سره وړاندې شي چې دوه لیتره د زیتونو تېل ورسره ګډ وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers15_verse_9.mp3', '', 1761754199, 1761754199),
(44059, 'Numbers 15:10', 'Numbers', 15, 10, 'دوه لیتره شراب دې هم د څښلو د نذرانې په توګه ورسره وي. د دې نذرانې بوی په څښتن باندې ښه لګیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers15_verse_10.mp3', '', 1761754199, 1761754199),
(44060, 'Numbers 15:14', 'Numbers', 15, 14, 'همدارنګه هغه پردي خلک چې ستاسو په منځ کې اوسیږي، که هغوی د موقت وخت دپاره وي یا تلپاتې وي هم باید د دغو مقرراتو څخه پیروي وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers15_verse_14.mp3', '', 1761754199, 1761754199),
(44061, 'Numbers 15:20', 'Numbers', 15, 20, 'کله چې تاسو ډوډۍ پخوئ، نو د لومړنۍ پېړې ډوډۍ چې د نوې غلې دانې څخه پخیږي هغه دې څښتن ته د ځانګړې نذرانې په توګه وړاندې شي. دا دې په هماغه ډول وړاندې شي لکه څنګه چې د غوبل شویو غلو دانو څخه تیاره شوې ځانګړې نذرانه وړاندې کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers15_verse_20.mp3', '', 1761754199, 1761754199),
(44062, 'Numbers 15:21', 'Numbers', 15, 21, 'دا ځانګړی سوغات دې د تل دپاره د هغې ډوډۍ څخه څښتن ته ورکول کیږي چې تاسو یې پخوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers15_verse_21.mp3', '', 1761754199, 1761754199),
(44063, 'Numbers 15:22', 'Numbers', 15, 22, 'خو فرض کړئ که چېرې یو څوک په سهوې سره د دغو مقرراتو څخه د ځینو په عملي کولو کې چې څښتن موسی ته ورکړي دي، بې پروایي وکړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers15_verse_22.mp3', '', 1761754199, 1761754199),
(44064, 'Numbers 15:23', 'Numbers', 15, 23, 'او فرض کړئ چې په راتلونکې کې د هغو ټولو شیانو په سرته رسولو کې چې څښتن د موسی په وسیله د هغو حکم کړی دی قوم بې پروایي وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers15_verse_23.mp3', '', 1761754199, 1761754199),
(44065, 'Numbers 15:24', 'Numbers', 15, 24, 'که چېرې دا کار په سهوې او په بې خبرۍ سره د قوم له خوا وشي، نو باید ټول قوم یو غویی د سوځېدونکې نذرانې دپاره چې بوی یې په څښتن باندې ښه لګیږي وړاندې کړي. دا نذرانه دې د پورته یادې شوې غلې دانې د نذرانې او څښلو د نذرانې سره یوځای او د یو سېرلي سره چې د ګناه د نذرانې په توګه وړاندې کیږي، وړاندې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers15_verse_24.mp3', '', 1761754199, 1761754199),
(44066, 'Numbers 15:25', 'Numbers', 15, 25, 'کاهن به د اسراییلو د ټول قوم دپاره کفاره ادا کړي او هغوی به وبخښل شي، ځکه چې دا کار په قصدي توګه نه ؤ شوی او هغوی څښتن ته د خپلې غلطۍ دپاره یوه داسې نذرانه چې په اور باندې تیاریږي او د ګناه یوه نذرانه راوړله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers15_verse_25.mp3', '', 1761754199, 1761754199),
(44067, 'Numbers 15:26', 'Numbers', 15, 26, 'د اسراییلو ټول قوم او هغه پردي خلک به چې د هغوی په منځ کې اوسیږي وبخښل شي، ځکه چې ټول په دې غلطۍ کې شامل وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers15_verse_26.mp3', '', 1761754199, 1761754199),
(44068, 'Numbers 15:27', 'Numbers', 15, 27, 'خو که چېرې ستاسو څخه یو تن په سهوې سره ګناه وکړي، نو باید یوه یو کلنه وزه د ګناه د نذرانې په توګه قرباني کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers15_verse_27.mp3', '', 1761754199, 1761754199),
(44069, 'Numbers 15:28', 'Numbers', 15, 28, 'کاهن دې د څښتن په حضور کې د هغه چا دپاره چې په سهوې سره یې ګناه کړې ده کفاره ادا کړي، نو هغه به وبخښل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers15_verse_28.mp3', '', 1761754199, 1761754199),
(44070, 'Numbers 15:29', 'Numbers', 15, 29, 'همدا قانون به په هغو ټولو خلکو باندې عملي کیږي چې په سهوې سره یې ګناه کړې وي، که هغوی اصلي اسراییلیان وي یا پردي اوسېدونکي وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers15_verse_29.mp3', '', 1761754199, 1761754199),
(44071, 'Numbers 15:30', 'Numbers', 15, 30, 'خو که چېرې ستاسو څخه څوک په قصدي توګه ګناه وکړي، که هغه اصلي اوسېدونکی وي یا پردی وي، هغه څښتن ته په سپکاوي کولو سره ګناهکار دی او باید ووژل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers15_verse_30.mp3', '', 1761754199, 1761754199),
(44072, 'Numbers 15:31', 'Numbers', 15, 31, 'ځکه څه چې څښتن ویلي دي، هغه نه دي منلي او په قصدي توګه یې د هغه یو حکم مات کړی دی. نو خون به یې په خپله غاړه وي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers15_verse_31.mp3', '', 1761754199, 1761754199),
(44073, 'Numbers 15:32', 'Numbers', 15, 32, 'یوځل کله چې اسراییلیانو په دښته کې سفر کاوه، د سبت په ورځ یو سړی د لرګیو په راټولولو ونیول شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers15_verse_32.mp3', '', 1761754199, 1761754199),
(44074, 'Numbers 15:33', 'Numbers', 15, 33, 'هغه موسی، هارون او ټول قوم ته وروستل شو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers15_verse_33.mp3', '', 1761754199, 1761754199),
(44075, 'Numbers 15:34', 'Numbers', 15, 34, 'او هغه یې تر څارنې لاندې وساته، ځکه دا معلومه نه وه چې د هغه سره به څه کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers15_verse_34.mp3', '', 1761754199, 1761754199),
(44076, 'Numbers 15:35', 'Numbers', 15, 35, 'بیا څښتن موسی ته وویل: «هغه سړی باید ووژل شي، ټول قوم دې هغه د کمپ څخه دباندې سنګسار کړي چې مړ شي!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers15_verse_35.mp3', '', 1761754199, 1761754199),
(44077, 'Numbers 15:36', 'Numbers', 15, 36, 'نو لکه څنګه چې څښتن حکم کړی ؤ، ټول قوم هغه د کمپ څخه دباندې وویست او سنګسار یې کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers15_verse_36.mp3', '', 1761754199, 1761754199),
(44078, 'Numbers 15:37', 'Numbers', 15, 37, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers15_verse_37.mp3', '', 1761754199, 1761754199),
(44079, 'Numbers 15:38', 'Numbers', 15, 38, '«د اسراییلو قوم ته ووایه چې د خپلو کالیو په څنډو پورې زونډي وګنډئ او په هر زونډي پورې یو یو ابي تار وتړئ. دا کار باید د تل دپاره وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers15_verse_38.mp3', '', 1761754199, 1761754199),
(44080, 'Numbers 15:41', 'Numbers', 15, 41, 'زه ستاسو څښتن خدای یم چې تاسو مې د مصر څخه راوویستلئ چې ستاسو خدای اوسم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers15_verse_41.mp3', '', 1761754199, 1761754199),
(44081, 'Psalms 141:1', 'Psalms', 141, 1, 'تاته زاري کوم څښتنه همدا‌اوس راسره وکړه مرسته کله چې تاته کړم زاري نو ته مې واوره اواز', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms141_verse_1.mp3', '', 1761754199, 1761754199),
(44082, 'Psalms 141:2', 'Psalms', 141, 2, 'ته قبوله کړه دعا زما لکه د خوشبویۍ په شان ما لاسونه پورته کړي په دعا کې ته قبوله یې کړه لکه چې څنګه قبلوې ته د ماښام قرباني', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms141_verse_2.mp3', '', 1761754199, 1761754199),
(44083, 'Psalms 141:3', 'Psalms', 141, 3, 'ای څښتنه، راسره مرسته وکړه چې وساتمه خپله خوله په واک کې چې بدې خبرې مې ونه وځي له شونډو څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms141_verse_3.mp3', '', 1761754199, 1761754199),
(44084, 'Psalms 141:4', 'Psalms', 141, 4, 'ومې ساته چې شوقمن نه شم زه د بدو کارو مه مې پرېږده چې شم شریک د بدو خلکو په کارونو کې زه او شریک دې نه شم د هغوی په مېلمستیاوو کې زه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms141_verse_4.mp3', '', 1761754199, 1761754199),
(44085, 'Psalms 141:5', 'Psalms', 141, 5, 'چې نېک سړی مې وهي نو مهرباني به یې وي که رټي مې هغه دا به وي د ښې دوا په شان چې زه یې رد نه کړمه خو زه دعا کومه تل د بدکارانو د عملونو په ضد', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms141_verse_5.mp3', '', 1761754199, 1761754199),
(44086, 'Psalms 141:6', 'Psalms', 141, 6, 'د ګړنګونو نه چې کله راګوزار شي حاکمان د هغوی بدکاره خلک به اقرار وکړي چې خبرې وې رښتیا زما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms141_verse_6.mp3', '', 1761754199, 1761754199),
(44087, 'Psalms 141:7', 'Psalms', 141, 7, 'هغوی به وایي: «لکه څنګه چې قلبه کوي څوک او میده کوي خاورې داسې خواره واره پراته به وي زمونږ هډوکي د قبر خوله کې»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms141_verse_7.mp3', '', 1761754199, 1761754199),
(44088, 'Psalms 141:8', 'Psalms', 141, 8, 'خو سترګې په لاره یمه زه تاته د کومک دپاره ای څښتن تعالی تا نه پناه غواړمه مه مې پرېږده چې مړ شم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms141_verse_8.mp3', '', 1761754199, 1761754199),
(44089, 'Psalms 141:9', 'Psalms', 141, 9, 'ومې ساته هغو دامونو څخه چې راته ایښي هغوی د بدکارانو د تیلکونو څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms141_verse_9.mp3', '', 1761754199, 1761754199),
(44090, 'Psalms 141:10', 'Psalms', 141, 10, 'بدکاران دې شي راګېر خپلو دامونو کې او زه ترې تېر شم روغ رمټ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms141_verse_10.mp3', '', 1761754199, 1761754199),
(44091, 'Leviticus 21:1', 'Leviticus', 21, 1, 'څښتن موسی ته وویل: «د کاهنانو یعنې د هارون د زامنو سره خبرې وکړه او ورته ووایه: هېڅ یو کاهن باید د خپلوانو د مړي د جنازې په مراسمو کې په ګډون کولو سره خپل ځان ناپاک نه کړي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus21_verse_1.mp3', '', 1761754199, 1761754199),
(44092, 'Leviticus 21:2', 'Leviticus', 21, 2, 'پرته له یو نژدې خپلوان څخه لکه د هغه مور یا پلار، د هغه زوی یا لور، د هغه سکه ورور،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus21_verse_2.mp3', '', 1761754199, 1761754199),
(44093, 'Leviticus 21:3', 'Leviticus', 21, 3, 'یا یوه پېغله خور چې واده شوې نه وي او مېړه نه لري چې هغه وساتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus21_verse_3.mp3', '', 1761754199, 1761754199),
(44094, 'Leviticus 21:4', 'Leviticus', 21, 4, 'هغه به خپل ځان د هغه چا په مرګ باندې نه ناپاکه کوي چې د واده په وسیله د هغه خپلوان شوی وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus21_verse_4.mp3', '', 1761754199, 1761754199),
(44095, 'Leviticus 21:5', 'Leviticus', 21, 5, 'هېڅ کاهن به په دې خاطر چې هغه داسې ښکاره شي چې د چا په مرګ باندې غمجن دی، نه به د خپل سر کومه برخه خرایي، نه به خپله ږیره لنډوي او نه به خپل بدن غوڅوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus21_verse_5.mp3', '', 1761754199, 1761754199),
(44096, 'Leviticus 21:6', 'Leviticus', 21, 6, 'هغه باید پاک او سپېڅلی وي او زما نوم سپک نه کړي، ځکه چې هغه ماته په اور باندې د خوړو نذرانې تیاروي او باید سپېڅلی وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus21_verse_6.mp3', '', 1761754199, 1761754199),
(44097, 'Leviticus 21:7', 'Leviticus', 21, 7, 'یو کاهن باید د یوې داسې ښځې سره واده ونه کړي چې هغه بدلمنه وي یا پېغله نه وي او یا د خپل مېړه له خوا ورته طلاق ورکړای شوی وي، ځکه چې هغه خپل خدای ته سپېڅلی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus21_verse_7.mp3', '', 1761754199, 1761754199),
(44098, 'Leviticus 21:8', 'Leviticus', 21, 8, 'خلک باید کاهن سپېڅلی وګڼي، ځکه چې هغه ماته د خوړو نذرانې وړاندې کوي. زه څښتن یم، زه سپېڅلی یم او خپل خلک سپېڅلي کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus21_verse_8.mp3', '', 1761754199, 1761754199),
(44099, 'Leviticus 21:9', 'Leviticus', 21, 9, 'که چېرې د یو کاهن لور بدلمنه شي، نو هغه خپل پلار رسوا کوي او باید وسوځول شي چې مړه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus21_verse_9.mp3', '', 1761754199, 1761754199),
(44100, 'Leviticus 21:10', 'Leviticus', 21, 10, 'لوی کاهن چې په سر باندې یې د مسح کولو تېل اچول شوي دي او د دې دپاره وقف شوی دی چې د کاهنتوب کالي واغوندي، نو باید خپل ویښتان ګډوډ پرېنږدي او خپل کالي ونه شلوي چې داسې ښکاره شي چې هغه د چا په مرګ باندې غمجن دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus21_verse_10.mp3', '', 1761754199, 1761754199),
(44101, 'Leviticus 21:13', 'Leviticus', 21, 13, 'هغه باید د داسې انجلۍ سره واده وکړي چې پېغله وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus21_verse_13.mp3', '', 1761754199, 1761754199),
(44102, 'Leviticus 21:14', 'Leviticus', 21, 14, 'هغه باید د یوې کونډې یا طلاق شوې یا د داسې ښځې سره واده ونه کړي چې هغه بدلمنه وي، خو یوازې د خپلې قبیلې څخه د یوې پېغلې سره دې واده وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus21_verse_14.mp3', '', 1761754199, 1761754199),
(44103, 'Leviticus 21:15', 'Leviticus', 21, 15, 'که نه، نو د هغه اولادونه چې باید سپېڅلي وي، هغوی به ناپاک وي. زه څښتن یم او ما هغه د لوی کاهن په توګه غوره کړی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus21_verse_15.mp3', '', 1761754199, 1761754199),
(44104, 'Leviticus 21:16', 'Leviticus', 21, 16, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus21_verse_16.mp3', '', 1761754199, 1761754199),
(44105, 'Leviticus 21:17', 'Leviticus', 21, 17, '«هارون ته ووایه چې ستا د اولادې څخه هېڅ یو سړی چې جسماني عیبونه ولري، نه شي کولای چې ماته د خوړو نذرانه وړاندې کړي. دا خبره به تل ترتله عملي کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus21_verse_17.mp3', '', 1761754199, 1761754199),
(44106, 'Leviticus 21:18', 'Leviticus', 21, 18, 'هېڅ یو سړی چې جسماني عیبونه په کې وي، نه شي کولای چې هغه نذرانه وړاندې کړي لکه څوک چې ړوند وي، ګوډ وي، بدشکله یا بې ډوله وي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus21_verse_18.mp3', '', 1761754199, 1761754199),
(44107, 'Leviticus 21:19', 'Leviticus', 21, 19, 'د چا لاس یا پښه چې معیوبه وي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus21_verse_19.mp3', '', 1761754199, 1761754199),
(44108, 'Leviticus 21:20', 'Leviticus', 21, 20, 'څوک په ملا باندې کړوپ وي یا ټیټ قدی وي، څوک چې د سترګې یا د پوستکي په ناروغۍ اخته وي او څوک چې خصي وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus21_verse_20.mp3', '', 1761754199, 1761754199),
(44109, 'Leviticus 21:21', 'Leviticus', 21, 21, 'د هارون کاهن د اولادې څخه هېڅ یو سړی چې کوم جسماني عیبونه په کې وي، نه شي کولای چې ماته د خوړو یوه داسې نذرانه وړاندې کړي چې په اور باندې تیاریږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus21_verse_21.mp3', '', 1761754199, 1761754199),
(44110, 'Leviticus 21:22', 'Leviticus', 21, 22, 'داسې سړی کولای شي چې هغه خواړه وخوري چې ماته وړاندې شوي وي، یعنې د خوړو سپېڅلې نذرانه او د خوړو ډېره سپېڅلې نذرانه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus21_verse_22.mp3', '', 1761754199, 1761754199);